#!/usr/bin/env python3
"""Offline SIP identity boundary processor (identity boundary protocol, rev 1).

Reads one JSON batch object on stdin and writes one JSON result object on
stdout.  No network, no child processes, standard library only.
"""

import json
import re
import sys

MAX_REQUEST_CHARS = 32768
MAX_HEADER_LINES = 512
MAX_FIELDS = 128
ANONYMOUS = 'sip:anonymous@anonymous.invalid'

UPSTREAM = 'upstream'
SYNTAX = 'syntax'
UNAUTHENTICATED = 'unauthenticated'
IDENTITY = 'identity'

_UPPER = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
_LOWER = 'abcdefghijklmnopqrstuvwxyz'
_DIG = '0123456789'
# Header/parameter/display token characters.
TOKEN_CHARS = frozenset(_UPPER + _LOWER + _DIG + "-.!%*_+`'~")
# sip URI user characters (after a single round of escape decoding).
USER_CHARS = frozenset(_UPPER + _LOWER + _DIG + "-_.!~*'()+")
HEX_CHARS = frozenset(_DIG + 'abcdefABCDEF')
WS = ' \t'

CONTROL_RE = re.compile('[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]')
HOST_RE = re.compile('[A-Za-z0-9.-]+')
LABEL_RE = re.compile('[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?')
DIGITS_RE = re.compile('[0-9]+')
CALLID_RE = re.compile('[A-Za-z0-9_.@+-]{1,128}')
CSEQ_RE = re.compile('([0-9]+)[ \t]+(.+)')

COMPACT = {'f': 'from', 't': 'to', 'i': 'call-id',
           'l': 'content-length', 'c': 'content-type'}
REQUIRED = ('from', 'to', 'call-id', 'cseq', 'content-length')
OPTIONAL_SINGLE = ('p-preferred-identity', 'remote-party-id', 'privacy',
                   'content-type')
SINGLETONS = frozenset(REQUIRED + OPTIONAL_SINGLE)
PAI_KEY = 'p-asserted-identity'


class Reject(Exception):
    """A decision has been reached; carry the reason string."""

    def __init__(self, reason):
        Exception.__init__(self, reason)
        self.reason = reason


def _syntax():
    raise Reject(SYNTAX)


# --------------------------------------------------------------------------
# URI grammar
# --------------------------------------------------------------------------

def _parse_user(user):
    """Decode and validate the user part; return it decoded or None."""
    if not user:
        return None
    out = []
    i = 0
    n = len(user)
    while i < n:
        c = user[i]
        if c == '%':
            if i + 2 >= n:
                return None
            h1 = user[i + 1]
            h2 = user[i + 2]
            if h1 not in HEX_CHARS or h2 not in HEX_CHARS:
                return None
            ch = chr(int(user[i + 1:i + 3], 16))
            if ch not in USER_CHARS:
                return None
            out.append(ch)
            i += 3
        elif c in USER_CHARS:
            out.append(c)
            i += 1
        else:
            return None
    return ''.join(out)


def _parse_host(host):
    """Validate and canonically lowercase a DNS host; return it or None."""
    if not host:
        return None
    if host.endswith('.'):
        core = host[:-1]
    else:
        core = host
    if not core or len(core) > 253:
        return None
    if HOST_RE.fullmatch(core) is None:
        return None
    for label in core.split('.'):
        if LABEL_RE.fullmatch(label) is None:
            return None
    return core.lower()


def _parse_tel(rest):
    if len(rest) < 2 or rest[0] != '+':
        return None
    digits = rest[1:]
    if DIGITS_RE.fullmatch(digits) is None:
        return None
    if len(digits) > 15 or digits[0] == '0':
        return None
    return 'tel:+' + digits


def _parse_sip(rest):
    if rest.count('@') != 1:
        return None
    user, host = rest.split('@')
    user = _parse_user(user)
    if user is None:
        return None
    host = _parse_host(host)
    if host is None:
        return None
    return 'sip:' + user + '@' + host


def parse_uri(text):
    """Lexically normalize a sip or tel URI, or return None if invalid."""
    if len(text) < 5:
        return None
    head = text[:4].lower()
    if head == 'sip:':
        return _parse_sip(text[4:])
    if head == 'tel:':
        return _parse_tel(text[4:])
    return None


# --------------------------------------------------------------------------
# Address grammar
# --------------------------------------------------------------------------

def _check_display(disp):
    """Validate the display-name region that precedes '<'."""
    d = disp.strip(' \t')
    if not d:
        return
    if d[0] == '"':
        i = 1
        n = len(d)
        esc = False
        closed = False
        while i < n:
            c = d[i]
            if esc:
                esc = False
            elif c == '\\':
                esc = True
            elif c == '"':
                closed = True
                i += 1
                break
            i += 1
        if not closed:
            _syntax()
        if d[i:].strip(' \t'):
            _syntax()
    else:
        for tok in d.split():
            for c in tok:
                if c not in TOKEN_CHARS:
                    _syntax()


def _scan_address(s, i):
    """Parse one address in s starting at index i.

    Returns (normalized_uri, index_after_address).  Raises Reject('syntax').
    """
    n = len(s)
    j = i
    inq = False
    esc = False
    lt = -1
    while j < n:
        c = s[j]
        if inq:
            if esc:
                esc = False
            elif c == '\\':
                esc = True
            elif c == '"':
                inq = False
        elif c == '"':
            inq = True
        elif c == '<':
            lt = j
            break
        j += 1
    if lt < 0:
        if inq or esc:
            _syntax()
        uri = parse_uri(s[i:])
        if uri is None:
            _syntax()
        return uri, n
    if i < lt:
        _check_display(s[i:lt])
    e = s.find('>', lt + 1)
    if e < 0:
        _syntax()
    uri = parse_uri(s[lt + 1:e].strip(' \t'))
    if uri is None:
        _syntax()
    return uri, e + 1


def _parse_tagged(value):
    """Parse a From/To value: one address plus an optional ;tag parameter."""
    n = len(value)
    uri, j = _scan_address(value, 0)
    tag = None
    while j < n and value[j] in ' \t':
        j += 1
    if j >= n:
        return uri, tag
    if value[j] != ';':
        _syntax()
    j += 1
    while j < n and value[j] in ' \t':
        j += 1
    k = j
    while k < n and value[k] not in ' \t=':
        k += 1
    name = value[j:k]
    while k < n and value[k] in ' \t':
        k += 1
    if k >= n or value[k] != '=':
        _syntax()
    k += 1
    while k < n and value[k] in ' \t':
        k += 1
    m = k
    while m < n and value[m] not in ' \t':
        m += 1
    tag_value = value[k:m]
    if not tag_value or len(tag_value) > 128:
        _syntax()
    for c in tag_value:
        if c not in TOKEN_CHARS:
            _syntax()
    while m < n and value[m] in ' \t':
        m += 1
    if m != n:
        _syntax()
    if name.lower() != 'tag':
        _syntax()
    return uri, tag_value


def _parse_plain_address(value):
    """Parse a PPI/RPID value: exactly one address, no header parameters."""
    uri, j = _scan_address(value, 0)
    if value[j:].strip(' \t'):
        _syntax()
    return uri


def _split_pai(value):
    """Split a PAI value on commas outside quoted strings and brackets."""
    parts = []
    n = len(value)
    start = 0
    inq = False
    esc = False
    depth = 0
    for i, c in enumerate(value):
        if inq:
            if esc:
                esc = False
            elif c == '\\':
                esc = True
            elif c == '"':
                inq = False
        elif c == '"':
            inq = True
        elif c == '<':
            depth += 1
        elif c == '>':
            depth -= 1
        elif c == ',' and depth == 0:
            parts.append(value[start:i])
            start = i + 1
    parts.append(value[start:])
    return parts


def _parse_pai_values(raw_values):
    addresses = []
    for raw in raw_values:
        for part in _split_pai(raw):
            part = part.strip(' \t')
            if not part:
                _syntax()
            uri, j = _scan_address(part, 0)
            if part[j:].strip(' \t'):
                _syntax()
            addresses.append(uri)
    if len(addresses) > 2:
        _syntax()
    if len(addresses) == 2:
        sip_count = 0
        for uri in addresses:
            if uri.startswith('sip:'):
                sip_count += 1
        if sip_count != 1:
            _syntax()
    return addresses


# --------------------------------------------------------------------------
# Request framing
# --------------------------------------------------------------------------

def _parse_fields(lines):
    """Unfold and split the header section into (name, raw value) pairs."""
    fields = []
    cur = None
    for line in lines:
        if not line:
            _syntax()
        first = line[0]
        if first == ' ' or first == '\t':
            if cur is None:
                _syntax()
            cur[1] = cur[1] + ' ' + line.lstrip(' \t')
        else:
            ci = line.find(':')
            if ci < 0:
                _syntax()
            name = line[:ci].rstrip(' \t')
            if not name:
                _syntax()
            for c in name:
                if c not in TOKEN_CHARS:
                    _syntax()
            cur = [name, line[ci + 1:]]
            fields.append(cur)
    return fields


def _parse_request(text):
    """Validate the whole request; return the parsed pieces we care about."""
    if len(text) > MAX_REQUEST_CHARS:
        _syntax()
    if not text.isascii():
        _syntax()
    if CONTROL_RE.search(text) is not None:
        _syntax()
    split = text.find('\r\n\r\n')
    if split < 0:
        _syntax()
    header = text[:split]
    body = text[split + 4:]
    squeezed = header.replace('\r\n', '')
    if '\r' in squeezed or '\n' in squeezed:
        _syntax()
    lines = header.split('\r\n')
    if len(lines) - 1 > MAX_HEADER_LINES:
        _syntax()
    request_line = lines[0]
    parts = request_line.split(' ')
    if len(parts) != 3 or parts[2] != 'SIP/2.0':
        _syntax()
    method = parts[0]
    if method != 'INVITE' and method != 'MESSAGE':
        _syntax()
    requri = parse_uri(parts[1])
    if requri is None or not requri.startswith('sip:'):
        _syntax()

    fields = _parse_fields(lines[1:])
    if len(fields) > MAX_FIELDS:
        _syntax()

    slot = {}
    pai_raw = []
    for name, value in fields:
        low = name.lower()
        key = COMPACT.get(low, low)
        stripped = value.strip(' \t')
        if key == PAI_KEY:
            pai_raw.append(stripped)
        elif key in SINGLETONS:
            if key in slot:
                _syntax()
            slot[key] = stripped
        # every other field is discarded after framing has been checked

    for key in REQUIRED:
        if key not in slot:
            _syntax()

    call_id = slot['call-id']
    if CALLID_RE.fullmatch(call_id) is None:
        _syntax()

    match = CSEQ_RE.fullmatch(slot['cseq'])
    if match is None:
        _syntax()
    if match.group(2) != method:
        _syntax()
    try:
        cseq = int(match.group(1))
    except ValueError:
        _syntax()
    if cseq < 1 or cseq > 2147483647:
        _syntax()

    raw_length = slot['content-length']
    if DIGITS_RE.fullmatch(raw_length) is None:
        _syntax()
    try:
        content_length = int(raw_length)
    except ValueError:
        _syntax()
    if content_length != len(body):
        _syntax()

    privacy = None
    if 'privacy' in slot:
        value = slot['privacy'].lower()
        if value != 'id' and value != 'none':
            _syntax()
        privacy = value

    content_type = None
    if 'content-type' in slot:
        content_type = slot['content-type']
        if not content_type:
            _syntax()

    from_uri, from_tag = _parse_tagged(slot['from'])
    to_uri, to_tag = _parse_tagged(slot['to'])

    ppi = None
    if 'p-preferred-identity' in slot:
        ppi = _parse_plain_address(slot['p-preferred-identity'])
    rpid = None
    if 'remote-party-id' in slot:
        rpid = _parse_plain_address(slot['remote-party-id'])
    pai = _parse_pai_values(pai_raw)

    claims = list(pai)
    if ppi is not None:
        claims.append(ppi)
    if rpid is not None:
        claims.append(rpid)
    for uri in claims:
        if uri == ANONYMOUS:
            _syntax()

    return {
        'method': method,
        'requri': requri,
        'from_uri': from_uri,
        'from_tag': from_tag,
        'from_anonymous': from_uri == ANONYMOUS,
        'to_uri': to_uri,
        'to_tag': to_tag,
        'call_id': call_id,
        'cseq': cseq,
        'privacy': privacy,
        'content_type': content_type,
        'ppi': ppi,
        'rpid': rpid,
        'pai': pai,
        'body': body,
    }


# --------------------------------------------------------------------------
# Directory
# --------------------------------------------------------------------------

def _identity_domain(canonical):
    if '@' in canonical:
        return canonical.rsplit('@', 1)[1].lower()
    return canonical.lower()


def build_directory(directory):
    """Return (alias map, canonical -> hosted domain map)."""
    aliases = {}
    domains = {}
    for canonical in directory:
        if not isinstance(canonical, str):
            continue
        aliases[canonical] = canonical
        domains[canonical] = _identity_domain(canonical)
    for canonical, alias_list in directory.items():
        if not isinstance(canonical, str) or not isinstance(alias_list, list):
            continue
        for alias in alias_list:
            if not isinstance(alias, str) or not alias:
                continue
            if alias not in aliases:
                aliases[alias] = canonical
            normalized = parse_uri(alias)
            if normalized is not None and normalized not in aliases:
                aliases[normalized] = canonical
    return aliases, domains


# --------------------------------------------------------------------------
# Boundary policy
# --------------------------------------------------------------------------

def _local_decision(parsed, ingress, gateway, accounts, aliases, domains):
    subject = ingress.get('subject')
    account = accounts.get(subject) if isinstance(subject, str) else None
    if not isinstance(account, dict):
        raise Reject(UNAUTHENTICATED)
    primary = account.get('primary')
    allowed = set()
    extra = account.get('allow')
    if isinstance(extra, list):
        for item in extra:
            if isinstance(item, str):
                allowed.add(item)
    allowed.add(primary)
    hosted = set()
    local = gateway.get('local_domains')
    if isinstance(local, list):
        for domain in local:
            if isinstance(domain, str):
                hosted.add(domain.lower())

    def authorized(canonical):
        if canonical is None or canonical not in allowed:
            return False
        domain = domains.get(canonical)
        return domain is not None and domain in hosted

    from_anonymous = parsed['from_anonymous']
    from_canonical = None
    if not from_anonymous:
        from_canonical = aliases.get(parsed['from_uri'])
        if not authorized(from_canonical):
            raise Reject(IDENTITY)
    ppi = parsed['ppi']
    ppi_canonical = None
    if ppi is not None:
        ppi_canonical = aliases.get(ppi)
        if not authorized(ppi_canonical):
            raise Reject(IDENTITY)

    if ppi is not None:
        selected = ppi_canonical
    elif not from_anonymous:
        selected = from_canonical
    else:
        selected = primary
        if not authorized(selected):
            raise Reject(IDENTITY)
    return selected, from_anonymous


def _peer_decision(parsed, ingress, gateway, aliases, domains):
    name = ingress.get('name')
    peers = gateway.get('peers')
    authority = None
    if isinstance(peers, dict) and isinstance(name, str):
        raw = peers.get(name)
        if isinstance(raw, list):
            authority = set()
            for domain in raw:
                if isinstance(domain, str):
                    authority.add(domain.lower())
    if authority is None:
        raise Reject(UNAUTHENTICATED)
    pai = parsed['pai']
    if not pai:
        raise Reject(UNAUTHENTICATED)
    resolved = []
    for uri in pai:
        canonical = aliases.get(uri)
        if canonical is None:
            raise Reject(IDENTITY)
        resolved.append(canonical)
    selected = resolved[0]
    for canonical in resolved[1:]:
        if canonical != selected:
            raise Reject(IDENTITY)
    domain = domains.get(selected)
    if domain is None or domain not in authority:
        raise Reject(IDENTITY)
    if not parsed['from_anonymous']:
        if aliases.get(parsed['from_uri']) != selected:
            raise Reject(IDENTITY)
    for uri in (parsed['ppi'], parsed['rpid']):
        if uri is not None and aliases.get(uri) != selected:
            raise Reject(IDENTITY)
    return selected, parsed['from_anonymous']


def _build_wire(parsed, selected, private, trusted_out):
    from_uri = ANONYMOUS if private else selected
    lines = [parsed['method'] + ' ' + parsed['requri'] + ' SIP/2.0']
    line = 'From: <' + from_uri + '>'
    if parsed['from_tag']:
        line += ';tag=' + parsed['from_tag']
    lines.append(line)
    line = 'To: <' + parsed['to_uri'] + '>'
    if parsed['to_tag']:
        line += ';tag=' + parsed['to_tag']
    lines.append(line)
    lines.append('Call-ID: ' + parsed['call_id'])
    lines.append('CSeq: %d %s' % (parsed['cseq'], parsed['method']))
    lines.append('Privacy: ' + ('id' if private else 'none'))
    if (not private) or trusted_out:
        lines.append('P-Asserted-Identity: <' + selected + '>')
    if parsed['content_type'] is not None:
        lines.append('Content-Type: ' + parsed['content_type'])
    lines.append('Content-Length: %d' % len(parsed['body']))
    return '\r\n'.join(lines) + '\r\n\r\n' + parsed['body']


def process_job(job, index, jobs, wires, aliases, domains, accounts, gateways):
    text = None
    if 'raw' in job:
        raw = job['raw']
        if not isinstance(raw, str):
            raise Reject(UPSTREAM)
        text = raw
    elif 'source' in job:
        source = job['source']
        if type(source) is not int:
            raise Reject(UPSTREAM)
        if source < 0 or source >= index:
            raise Reject(UPSTREAM)
        text = wires[source]
        if text is None:
            raise Reject(UPSTREAM)
    else:
        raise Reject(UPSTREAM)

    try:
        parsed = _parse_request(text)
    except Reject as exc:
        if exc.reason != SYNTAX:
            raise
        raise

    ingress = job.get('ingress')
    if not isinstance(ingress, dict):
        raise Reject(UNAUTHENTICATED)
    kind = ingress.get('kind')
    if kind == 'local':
        gateway = gateways.get(job.get('gateway'))
        if not isinstance(gateway, dict):
            raise Reject(UNAUTHENTICATED)
        selected, from_anonymous = _local_decision(
            parsed, ingress, gateway, accounts, aliases, domains)
        basis = 'local'
    elif kind == 'peer':
        gateway = gateways.get(job.get('gateway'))
        if not isinstance(gateway, dict):
            raise Reject(UNAUTHENTICATED)
        selected, from_anonymous = _peer_decision(
            parsed, ingress, gateway, aliases, domains)
        basis = 'peer'
    else:
        raise Reject(UNAUTHENTICATED)

    private = from_anonymous or parsed['privacy'] == 'id'
    trusted_out = bool(job.get('trusted_out'))
    wire = _build_wire(parsed, selected, private, trusted_out)
    return {
        'status': 'accept',
        'identity': selected,
        'basis': basis,
        'private': private,
        'wire': wire,
    }


def process_batch(batch):
    directory = batch.get('directory') or {}
    if not isinstance(directory, dict):
        directory = {}
    accounts = batch.get('accounts') or {}
    if not isinstance(accounts, dict):
        accounts = {}
    gateways = batch.get('gateways') or {}
    if not isinstance(gateways, dict):
        gateways = {}
    jobs = batch.get('jobs')
    if not isinstance(jobs, list):
        jobs = []

    aliases, domains = build_directory(directory)
    results = []
    wires = []
    for index, job in enumerate(jobs):
        if not isinstance(job, dict):
            result = {'status': 'reject', 'reason': UPSTREAM}
        else:
            try:
                result = process_job(job, index, jobs, wires, aliases, domains,
                                     accounts, gateways)
            except Reject as exc:
                result = {'status': 'reject', 'reason': exc.reason}
        if result.get('status') == 'accept':
            wires.append(result['wire'])
        else:
            wires.append(None)
        results.append(result)
    return {'results': results}


def main():
    data = sys.stdin.buffer.read()
    batch = json.loads(data.decode('utf-8'))
    if not isinstance(batch, dict):
        raise ValueError('batch must be a JSON object')
    output = process_batch(batch)
    sys.stdout.write(json.dumps(output))
    sys.stdout.write('\n')
    sys.stdout.flush()
    return 0


if __name__ == '__main__':
    try:
        code = main()
    except Reject as exc:
        sys.stderr.write('reject: %s\n' % exc.reason)
        code = 1
    sys.exit(code)
