def _parse_sip(rest):
    if rest.count('@') != 1:
        return None
    user, host = rest.split('@')
    user = _parse_user(user)
    if user is None:
        return None
    host = _parse_host(host)
    if host is None:
        return None
    return 'sip:' + user + '@' + host


def parse_uri(text):
    """Lexically normalize a sip or tel URI, or return None if invalid."""
    if len(text) < 5:
        return None
    head = text[:4].lower()
    if head == 'sip:':
        return _parse_sip(text[4:])
    if head == 'tel:':
        return _parse_tel(text[4:])
    return None


