# Request framing
# --------------------------------------------------------------------------

def _parse_fields(lines):
    """Unfold and split the header section into (name, raw value) pairs."""
    fields = []

    fields = []
    cur = None
    for line in lines:
        if not line:
            _syntax()
        first = line[0]
        if first == ' ' or first == '\t':
            if cur is None:
                _syntax()
            cur[1] = cur[1] + ' ' + line.lstrip(' \t')
        else:
            ci = line.find(':')
            if ci < 0:
                _syntax()
            name = line[:ci].rstrip(' \t')
            if not name:
                _syntax()
            for c in name:
                if c not in TOKEN_CHARS:
                    _syntax()
            cur = [name, line[ci + 1:]]
            fields.append(cur)
    return fields


def _parse_request(text):
    """Validate the whole request; return the parsed pieces we care about."""
    if len(text) > MAX_REQUEST_CHARS:
        _syntax()
    if not text.isascii():
