    squeezed = header.replace('\r\n', '')
    if '\r' in squeezed or '\n' in squeezed:
        _syntax()
    lines = header.split('\r\n')
    if len(lines) - 1 > MAX_HEADER_LINES:
        _syntax()
    request_line = lines[0]
    parts = request_line.split(' ')
    if len(parts) != 3 or parts[2] != 'SIP/2.0':
        _syntax()
    method = parts[0]
    if method != 'INVITE' and method != 'MESSAGE':
        _syntax()
    requri = parse_uri(parts[1])
    if requri is None or not requri.startswith('sip:'):
        _syntax()

    fields = _parse_fields(lines[1:])
    if len(fields) > MAX_FIELDS:
        _syntax()

    slot = {}
    pai_raw = []
    for name, value in fields:
        low = name.lower()
        key = COMPACT.get(low, low)
        stripped = value.strip(' \t')
        if key == PAI_KEY:
            pai_raw.append(stripped)
        elif key in SINGLETONS:
