    match = CSEQ_RE.fullmatch(slot['cseq'])
    if match is None:
        _syntax()
    if match.group(2) != method:
        _syntax()
    try:
        cseq = int(match.group(1))
    except ValueError:
        _syntax()
    if cseq < 1 or cseq > 2147483647:
        _syntax()

    raw_length = slot['content-length']
    if DIGITS_RE.fullmatch(raw_length) is None:
        _syntax()
    try:
        content_length = int(raw_length)
    except ValueError:
        _syntax()
    if content_length != len(body):
        _syntax()

    privacy = None
    if 'privacy' in slot:
        value = slot['privacy'].lower()
        if value != 'id' and value != 'none':
            _syntax()
        privacy = value

    content_type = None
    if 'content-type' in slot:
        content_type = slot['content-type']
        if not content_type:
            _syntax()

    from_uri, from_tag = _parse_tagged(slot['from'])
    to_uri, to_tag = _parse_tagged(slot['to'])

    ppi = None
    if 'p-preferred-identity' in slot:
