        'requri': requri,
        'from_uri': from_uri,
        'from_tag': from_tag,
        'from_anonymous': from_uri == ANONYMOUS,
        'to_uri': to_uri,
        'to_tag': to_tag,
        'call_id': call_id,
        'cseq': cseq,
        'privacy': privacy,
        'content_type': content_type,
        'ppi': ppi,
        'rpid': rpid,
        'pai': pai,
        'body': body,
    }


